#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"

// Destination-passing-style entry for hybrid attention-mask
// preparation. Per definition.json:
//
//   batch_size_scalar              : int64 0-D scalar
//   seq_length_scalar              : int64 0-D scalar
//   past_key_values_length_scalar  : int64 0-D scalar
//   full_attention_mask            : [B, num_heads=64, T, total_len] bool (DPS)
//   sliding_window_attention_mask  : [B, num_heads=64, T, total_len] bool (DPS)
//
// Const axes pinned by definition.json AND enforced on every
// tensor that the kernel indexes with that fixed assumption:
//   num_attention_heads     = 64    pinned on full_attention_mask
//   swa_num_attention_heads = 64    pinned on sliding_window_attention_mask
//   sliding_window          = 128   passed to launcher as a constant
//                                   (the reference's swa_mask
//                                   masked_fill is a no-op so
//                                   sliding_window does not affect
//                                   the output; see kernel.cu).

namespace {

constexpr int64_t kNumAttentionHeads = 64;
constexpr int64_t kSwaNumAttentionHeads = 64;
constexpr int64_t kSlidingWindow = 128;

}  // namespace

void run(
    int64_t batch_size_scalar,
    int64_t seq_length_scalar,
    int64_t past_key_values_length_scalar,
    torch::Tensor full_attention_mask,
    torch::Tensor sliding_window_attention_mask
) {
    const int64_t batch_size = batch_size_scalar;
    const int64_t seq_length = seq_length_scalar;
    const int64_t past_kv_length = past_key_values_length_scalar;

    TORCH_CHECK(batch_size > 0, "batch_size must be positive");
    TORCH_CHECK(seq_length > 0, "seq_length must be positive");
    TORCH_CHECK(past_kv_length >= 0,
                "past_kv_length must be non-negative");

    const int64_t total_length = seq_length + past_kv_length;

    TORCH_CHECK(full_attention_mask.is_cuda(),
                "full_attention_mask must be CUDA");
    TORCH_CHECK(sliding_window_attention_mask.is_cuda(),
                "sliding_window_attention_mask must be CUDA");

    TORCH_CHECK(full_attention_mask.dtype() == torch::kBool,
                "full_attention_mask must be bool");
    TORCH_CHECK(sliding_window_attention_mask.dtype() == torch::kBool,
                "sliding_window_attention_mask must be bool");

    TORCH_CHECK(full_attention_mask.is_contiguous(),
                "full_attention_mask must be contiguous");
    TORCH_CHECK(sliding_window_attention_mask.is_contiguous(),
                "sliding_window_attention_mask must be contiguous");

    TORCH_CHECK(full_attention_mask.dim() == 4,
                "full_attention_mask must be 4D "
                "[B, num_heads, T, total_length]");
    TORCH_CHECK(sliding_window_attention_mask.dim() == 4,
                "sliding_window_attention_mask must be 4D "
                "[B, num_heads, T, total_length]");

    TORCH_CHECK(full_attention_mask.size(0) == batch_size,
                "full_attention_mask.size(0) must equal "
                "batch_size_scalar, got ",
                full_attention_mask.size(0));
    TORCH_CHECK(full_attention_mask.size(1) == kNumAttentionHeads,
                "full_attention_mask.size(1) must equal "
                "num_attention_heads=64, got ",
                full_attention_mask.size(1));
    TORCH_CHECK(full_attention_mask.size(2) == seq_length,
                "full_attention_mask.size(2) must equal "
                "seq_length_scalar, got ",
                full_attention_mask.size(2));
    TORCH_CHECK(full_attention_mask.size(3) == total_length,
                "full_attention_mask.size(3) must equal "
                "seq_length + past_key_values_length, got ",
                full_attention_mask.size(3));

    TORCH_CHECK(sliding_window_attention_mask.size(0) == batch_size,
                "sliding_window_attention_mask.size(0) must equal "
                "batch_size_scalar");
    TORCH_CHECK(sliding_window_attention_mask.size(1)
                == kSwaNumAttentionHeads,
                "sliding_window_attention_mask.size(1) must equal "
                "swa_num_attention_heads=64");
    TORCH_CHECK(sliding_window_attention_mask.size(2) == seq_length,
                "sliding_window_attention_mask.size(2) must equal "
                "seq_length_scalar");
    TORCH_CHECK(sliding_window_attention_mask.size(3) == total_length,
                "sliding_window_attention_mask.size(3) must equal "
                "seq_length + past_key_values_length");

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_028_hybrid_attention_mask_preparation_launcher(
        batch_size, seq_length, past_kv_length, kSlidingWindow,
        full_attention_mask, sliding_window_attention_mask, stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "Hybrid attention-mask preparation: full causal mask + "
        "sliding-window mask. One pure-boolean CUDA kernel per "
        "(b, h, t) row writing both outputs in one pass. "
        "num_attention_heads=64, swa_num_attention_heads=64, "
        "sliding_window=128 pinned.");
}

#include "kernel.h"

#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

// One pure-boolean CUDA kernel that writes both the full causal
// attention mask and the sliding-window attention mask in a single
// pass over (b, h, t, j).
//
// Per-element math (matching the reference's two `masked_fill`
// operations exactly):
//
//   Full mask:
//     target_idx  = t
//     source_idx  = j - past_kv_length
//     causal_cond = (target_idx >= source_idx)
//     full_mask = torch.ones(...).masked_fill(causal_cond, False)
//        => full_attention_mask[b, h, t, j] = !causal_cond
//
//   Sliding-window mask:
//     swa_mask = torch.zeros(...).masked_fill(valid_positions, False)
//     This is a NO-OP: a buffer of False values filled with False at
//     the True positions yields a buffer of False values. The
//     reference's `valid_positions` computation has no observable
//     effect on the returned tensor. To match the canonical
//     reference bit-for-bit, the kernel writes `False` for every
//     (b, h, t, j) in sliding_window_attention_mask. The
//     reference's combine-with-window branch is therefore dead
//     code under the canonical workload contract.
//
// Kernel topology:
//   * Grid (B, num_heads, T). One CTA per (b, h, t) row.
//   * BLOCK_THREADS = up to 256; stride-loops over `total_length`.
//   * Each thread computes both bool outputs at (b, h, t, j) and
//     writes them via the contiguous row offsets.

namespace {

constexpr int kBlockThreads = 256;

__global__ void __launch_bounds__(kBlockThreads, 4)
    k_hybrid_attention_mask_preparation(
        bool* __restrict__ full_attention_mask,
        bool* __restrict__ sliding_window_attention_mask,
        int H,
        int T,
        int total_length,
        int past_kv_length
) {
    const int b = blockIdx.x;
    const int h = blockIdx.y;
    const int t = blockIdx.z;
    const int tid = threadIdx.x;

    const size_t row_offset = (((size_t)b * H + h) * T
                               + (size_t)t) * total_length;
    bool* __restrict__ full_row = full_attention_mask + row_offset;
    bool* __restrict__ swa_row =
        sliding_window_attention_mask + row_offset;

    const int target_idx = t;

    for (int j = tid; j < total_length; j += kBlockThreads) {
        const int source_idx = j - past_kv_length;
        const bool causal_cond = (target_idx >= source_idx);
        full_row[j] = !causal_cond;
        swa_row[j] = false;  // see header comment: reference's
                             // masked_fill on a zeros buffer with False
                             // is a no-op; the kernel emits the same.
    }
}

}  // namespace

void problem_028_hybrid_attention_mask_preparation_launcher(
    int64_t batch_size,
    int64_t seq_length,
    int64_t past_kv_length,
    int64_t sliding_window,
    torch::Tensor& full_attention_mask,
    torch::Tensor& sliding_window_attention_mask,
    cudaStream_t stream
) {
    const int B = static_cast<int>(batch_size);
    const int H = static_cast<int>(full_attention_mask.size(1));
    const int T = static_cast<int>(seq_length);
    const int total_length = static_cast<int>(seq_length
                                              + past_kv_length);

    dim3 grid(B, H, T);
    dim3 block(kBlockThreads);

    (void)sliding_window;  // see kernel comment: sliding-window mask is
                           // all-False under the reference's no-op
                           // masked_fill, so the kernel doesn't read
                           // sliding_window. The host launcher accepts
                           // it for runtime-check / API completeness.

    k_hybrid_attention_mask_preparation<<<grid, block, 0, stream>>>(
        full_attention_mask.data_ptr<bool>(),
        sliding_window_attention_mask.data_ptr<bool>(),
        H,
        T,
        total_length,
        static_cast<int>(past_kv_length)
    );

    TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                "problem_028 hybrid attention mask preparation kernel "
                "launch failed");
}

#pragma once

#include <torch/extension.h>
#include <cuda_runtime.h>

// Host launcher for the hybrid attention-mask preparation kernel:
//
//   For each (b in [0, B), h in [0, num_heads), t in [0, T),
//                   j in [0, total_length)):
//     causal_cond = (t >= j - past_kv_length)
//     full_attention_mask[b, h, t, j]           = !causal_cond
//     sliding_window_attention_mask[b, h, t, j] = false
//
// The sliding-window mask is unconditionally False because the
// reference's `swa_mask = torch.zeros(...).masked_fill(
// valid_positions, False)` is a no-op (a zeros buffer filled
// with False at True positions yields a zeros buffer). To match
// the canonical reference bit-for-bit the kernel writes False
// for every (b, h, t, j); the `sliding_window` constant is
// accepted by this launcher for API completeness but is unused
// by the kernel.
//
// Outputs (DPS):
//   full_attention_mask           : [B, num_heads=64, T, total_length] bool
//   sliding_window_attention_mask : [B, num_heads=64, T, total_length] bool
//
// Inputs are passed as int64 host scalars. num_attention_heads = 64,
// swa_num_attention_heads = 64, and sliding_window = 128 are pinned
// by the problem definition; batch_size, seq_length,
// past_key_values_length vary.
void problem_028_hybrid_attention_mask_preparation_launcher(
    int64_t batch_size,
    int64_t seq_length,
    int64_t past_kv_length,
    int64_t sliding_window,
    torch::Tensor& full_attention_mask,
    torch::Tensor& sliding_window_attention_mask,
    cudaStream_t stream);
